\title{The Suspension Tower and the Exact $\Zt$-Coindex of Combinatorial Spheres}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
We study antipodal (equivariant) simplicial maps between combinatorial spheres realized as
boundaries of cross-polytopes, equipped with the free $\Zt$-action given by the antipodal map. We
prove that such a map $S^m \to S^n$ exists if and only if $m \le n$, giving a completely elementary,
all-dimensions form of the Borsuk--Ulam theorem in this model. The engine of the result is a
structural characterization we call the \emph{Coordinate Injectivity Principle}: an equivariant
simplicial self-map of cross-polytopes is simplicial precisely when the induced map on coordinate
axes is injective, with signs entirely free. As consequences we obtain the exact value of the
$\Zt$-coindex, $\coind(S^n) = n$; the construction of the $k$-fold \emph{suspension tower} as a
functor on equivariant maps; and the \emph{exactness} of the tower --- suspension preserves the
excess $n - m$, so a fair map exists at level $k$ if and only if it exists at the base, and every
level of the tower is Borsuk--Ulam sharp.
\end{abstract}

\maketitle

\section{Introduction}

The Borsuk--Ulam theorem asserts that every continuous antipodal map $S^m \to S^n$ forces $m \le n$;
equivalently, there is no continuous map $S^{n+1} \to S^n$ commuting with the antipodal involution.
A standard invariant packaging its content is the \emph{$\Zt$-coindex} of a free $\Zt$-space $X$: the
largest $m$ such that there is an equivariant map $S^m \to X$; Borsuk--Ulam is the statement
$\coind(S^n) = n$.

This paper develops a fully combinatorial and elementary account in the \emph{cross-polytope model},
in which spheres are boundaries of orthoplexes and maps are simplicial and antipodally equivariant.
Our central technical observation reduces the entire simpliciality condition to injectivity of a
finite map on axis labels, whence all impossibility statements become instances of the pigeonhole
principle. We further construct the iterated \emph{suspension tower} and prove that every rung is
Borsuk--Ulam sharp.

\subsection*{Contributions}
\begin{enumerate}
  \item The \textbf{Coordinate Injectivity Principle} (Theorem~\ref{thm:cip}): simpliciality of an
  equivariant vertex map $\iff$ injectivity of its induced coordinate map.
  \item \textbf{Exact existence criterion} (Theorem~\ref{thm:exist}): a fair map $S^m \to S^n$ exists
  $\iff m \le n$.
  \item \textbf{Borsuk--Ulam in all dimensions} (Corollary~\ref{cor:bu}).
  \item \textbf{Exact coindex} (Theorem~\ref{thm:coind}): $\coind(S^n) = n$.
  \item \textbf{The suspension tower} and its \textbf{exactness and sharpness}
  (Theorems~\ref{thm:exact}--\ref{thm:sharp}).
\end{enumerate}

\section{The cross-polytope model}

\begin{definition}[Combinatorial sphere]
For $n \in \mathbb{N}$, the \emph{$n$-dimensional combinatorial sphere} $S^n$ is the boundary complex
of the $(n{+}1)$-dimensional cross-polytope, with vertex set the signed standard basis vectors
$\{\pm e_0, \dots, \pm e_n\}$. We encode a vertex as a pair $(i,b) \in \{0,\dots,n\} \times
\{\true,\false\}$, where $i$ is the axis index and $b$ the sign. We write $\SVert(n)$ for this set;
$|\SVert(n)| = 2(n{+}1)$. A pair $\{u,v\}$ spans an edge iff $u \ne v$ and $u \ne -v$.
\end{definition}

\begin{definition}[Antipodal map]
The free $\Zt$-action is $\anti(i,b) = (i, \lnot b)$.
\end{definition}

\begin{lemma}
For all $p$: $\anti(\anti(p)) = p$ and $\anti(p) \ne p$. Hence $S^n$ is a free $\Zt$-complex.
\end{lemma}
\begin{proof}
Flipping a bit twice restores it; a Boolean value never equals its negation.
\end{proof}

\begin{definition}[Fair map / $\Zt$-map]
A \emph{$\Zt$-map} $F : S^m \to S^n$ is a vertex map $F : \SVert(m) \to \SVert(n)$ that is
\emph{equivariant} ($F(\anti(p)) = \anti(F(p))$ for all $p$) and \emph{simplicial} (for all $p,q$,
$F(p) = \anti(F(q))$ implies $p = \anti(q)$). We write $\Ztmap(m,n)$ for the set of such maps.
\end{definition}

The simpliciality clause forbids two non-antipodal vertices from mapping to an antipodal (non-face)
pair. The identity is a $\Zt$-map, so $\Ztmap(n,n) \ne \varnothing$.

\section{Reduction to positive-vertex data}

\begin{definition}[Induced map]
Given $g : \{0,\dots,m\} \to \SVert(n)$, define $\induced(g) : \SVert(m) \to \SVert(n)$ by
$\induced(g)(i,\true) = g(i)$ and $\induced(g)(i,\false) = \anti(g(i))$.
\end{definition}

\begin{lemma}\label{lem:indeq}
$\induced(g)$ is equivariant for every $g$.
\end{lemma}
\begin{proof}
Immediate from the definition and $\anti\circ\anti = \mathrm{id}$.
\end{proof}

\begin{proposition}[Positive-vertex reduction]\label{prop:pos}
$\Ztmap(m,n) \ne \varnothing$ iff there exists $g$ such that $\induced(g)$ is simplicial.
\end{proposition}
\begin{proof}
($\Rightarrow$) Given $F$, set $g(i) = F(i,\true)$; equivariance gives $\induced(g) = F$, which is
simplicial. ($\Leftarrow$) By Lemma~\ref{lem:indeq}, $\induced(g)$ is equivariant, and the hypothesis
is simpliciality, so $\induced(g) \in \Ztmap(m,n)$.
\end{proof}

\section{The Coordinate Injectivity Principle}

\begin{definition}[Coordinate map]
For $g$, its \emph{coordinate map} is $\sigma = \coordMap(g) : \{0,\dots,m\} \to \{0,\dots,n\}$,
$\sigma(i) = (g(i))_1$, the axis index of $g(i)$.
\end{definition}

\begin{theorem}[Coordinate Injectivity Principle]\label{thm:cip}
$\induced(g)$ is simplicial if and only if $\sigma = \coordMap(g)$ is injective.
\end{theorem}
\begin{proof}
\emph{(Simplicial $\Rightarrow$ injective.)} Suppose $\sigma(i) = \sigma(j)$. If the signs of $g(i),
g(j)$ agree then $g(i) = g(j)$, and $\induced(g)(i,\true) = \anti(\induced(g)(j,\false))$ gives, by
simpliciality, $(i,\true) = \anti(j,\false) = (j,\true)$, so $i = j$. If the signs differ then $g(i)
= \anti(g(j))$ and $\induced(g)(i,\true) = \anti(\induced(g)(j,\true))$ gives $(i,\true) = (j,\false)$,
impossible; so this subcase does not arise. Thus $\sigma$ is injective.

\emph{(Injective $\Rightarrow$ simplicial.)} Suppose $\induced(g)(i,b) = \anti(\induced(g)(j,c))$.
The antipodal map and the induced-map cases preserve the axis component, so comparing axes gives
$\sigma(i) = \sigma(j)$, whence $i = j$ by injectivity. With $i = j$, comparing signs forces
$b = \lnot c$, i.e. $(i,b) = \anti(j,c)$.
\end{proof}

\noindent\textbf{Interpretation.} A fair simplicial self-map of cross-polytopes injectively relabels
coordinate axes with arbitrary independent signs; signs are gauge, and the only obstruction is axis
collision.

\section{Existence criterion and Borsuk--Ulam}

\begin{theorem}[Existence criterion]\label{thm:exist}
$\Ztmap(m,n) \ne \varnothing$ if and only if $m \le n$.
\end{theorem}
\begin{proof}
By Proposition~\ref{prop:pos} and Theorem~\ref{thm:cip}, nonemptiness is equivalent to the existence
of an injection $\sigma : \{0,\dots,m\} \hookrightarrow \{0,\dots,n\}$, which exists iff $m+1 \le n+1$,
i.e. $m \le n$. For the construction, take $g(i) = (i,\true)$ with $\sigma$ the inclusion.
\end{proof}

\begin{corollary}[Borsuk--Ulam, all dimensions]\label{cor:bu}
For every $n$, $\Ztmap(n+1,n) = \varnothing$: there is no fair map $S^{n+1} \to S^n$.
\end{corollary}
\begin{proof}
This would require $n+1 \le n$.
\end{proof}

\section{The exact coindex}

\begin{definition}
$\coind(S^n) = \sup\{ m \in \mathbb{N} : \Ztmap(m,n) \ne \varnothing \}$.
\end{definition}

\begin{theorem}[Exact coindex]\label{thm:coind}
$\coind(S^n) = n$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:exist} the admissible set is $\{0,1,\dots,n\}$, with supremum $n$.
\end{proof}

\section{The suspension tower}

\begin{definition}[Suspended vertex]
For $p = (i,b) \in \SVert(n)$, let $\suspV(p) = (\hat\imath, b) \in \SVert(n+1)$, where $\hat\imath$
is the image of $i$ under the inclusion $\{0,\dots,n\} \hookrightarrow \{0,\dots,n+1\}$; the new axis
$n{+}1$ is the pole.
\end{definition}

\begin{definition}[Suspension of a map]
For $F \in \Ztmap(m,n)$, define $\susp(F) : \SVert(m+1) \to \SVert(n+1)$ sending the new source pole
$(\text{pole},b)$ to the new target pole $(\text{pole},b)$, and each old vertex $(\hat\jmath,b)$ to
$\suspV(F(j,b))$.
\end{definition}

\begin{proposition}
$\susp(F) \in \Ztmap(m+1,n+1)$.
\end{proposition}
\begin{proof}[Proof sketch]
Equivariance holds on the pole (sign bit flips) and on old axes ($\suspV$ commutes with $\anti$, $F$
equivariant). For simpliciality, the pole axis exceeds every old axis, so pole images match only pole
images and old images only old images; the pole case forces $p = \anti(q)$ by signs, and the old case
reduces via injectivity of $\suspV$ to simpliciality of $F$.
\end{proof}

\begin{definition}[$k$-fold suspension]
$\operatorname{suspIter}^0(F) = F$, $\operatorname{suspIter}^{k+1}(F) = \susp(\operatorname{suspIter}^{k}(F))$,
mapping $\Ztmap(m,n) \to \Ztmap(m+k,n+k)$. The spheres $S^n, S^{n+1}, \dots$ with these functors form
the \emph{suspension tower}.
\end{definition}

\begin{theorem}[Constructive raising]
If $\Ztmap(m,n) \ne \varnothing$ then $\Ztmap(m+k,n+k) \ne \varnothing$ for all $k$.
\end{theorem}
\begin{proof}
Apply $\operatorname{suspIter}^k$.
\end{proof}

\begin{theorem}[Exactness of the tower]\label{thm:exact}
For all $m,n,k$: $\Ztmap(m+k,n+k) \ne \varnothing \iff \Ztmap(m,n) \ne \varnothing$. Equivalently,
suspension preserves the excess $n-m$ exactly.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:exist} both sides reduce to $m + k \le n + k$ and $m \le n$, which are equivalent.
\end{proof}

\begin{theorem}[Sharpness at every level]\label{thm:sharp}
For all $n,k$: $\Ztmap(n+k+1, n+k) = \varnothing$.
\end{theorem}
\begin{proof}
Apply Corollary~\ref{cor:bu} with $n$ replaced by $n+k$.
\end{proof}

\begin{corollary}
$\coind(S^{n+k}) = n + k = \coind(S^n) + k$: the coindex rises by exactly one per rung.
\end{corollary}

\section{Discussion}

The Coordinate Injectivity Principle collapses a family of impossibility theorems onto the pigeonhole
principle and makes the coindex a complete invariant equal to the dimension, with the suspension tower
exact. The equivalence ``simplicial antipodal map $\iff$ coordinate injection'' is special to
cross-polytopes; for a general free simplicial $\Zt$-complex $K$ the coindex is not determined by
dimension alone, and the upper bound $\coind(K) \le \dim K$ genuinely requires Tucker's lemma. The
present model is thus a transparent laboratory in which the mechanism is fully exposed.

\section*{Future directions}
Formalize Tucker's lemma to recover $\coind(K) \le \dim K$ for arbitrary free $\Zt$-complexes; study
the index/coindex gap; connect the coindex to chromatic lower bounds; and generalize to free actions
of arbitrary finite groups.

\end{document}

