"""Existence oracle and brute-force verifier for fair maps S^m -> S^n."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Tuple

Vertex = Tuple[int, bool]

def anti(p: Vertex) -> Vertex:
    i, b = p
    return (i, not b)

def svert(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]

def induced(g: List[Vertex]) -> Dict[Vertex, Vertex]:
    f: Dict[Vertex, Vertex] = {}
    for i, v in enumerate(g):
        f[(i, True)] = v
        f[(i, False)] = anti(v)
    return f

def is_simplicial(f: Dict[Vertex, Vertex]) -> bool:
    return all(not (f[p] == anti(f[q]) and p != anti(q)) for p in f for q in f)

def exists_closed_form(m: int, n: int) -> bool:
    return m <= n

def exists_bruteforce(m: int, n: int) -> bool:
    return any(is_simplicial(induced(list(g))) for g in product(svert(n), repeat=m + 1))

if __name__ == "__main__":
    for n in range(4):
        for m in range(4):
            assert exists_bruteforce(m, n) == exists_closed_form(m, n)
            print(f"S^{m} -> S^{n}: exists = {exists_closed_form(m, n)}")
    print("All existence checks agree with the criterion m <= n.")

"""Verify the Coordinate Injectivity Principle by exhaustive search."""
from __future__ import annotations
from itertools import product
from typing import Dict, List, Tuple

Vertex = Tuple[int, bool]

def anti(p: Vertex) -> Vertex:
    i, b = p
    return (i, not b)

def svert(n: int) -> List[Vertex]:
    return [(i, b) for i in range(n + 1) for b in (True, False)]

def induced(g: List[Vertex]) -> Dict[Vertex, Vertex]:
    f: Dict[Vertex, Vertex] = {}
    for i, v in enumerate(g):
        f[(i, True)] = v
        f[(i, False)] = anti(v)
    return f

def is_simplicial(f: Dict[Vertex, Vertex]) -> bool:
    return all(not (f[p] == anti(f[q]) and p != anti(q)) for p in f for q in f)

def coord_injective(g: List[Vertex]) -> bool:
    axes = [v[0] for v in g]
    return len(set(axes)) == len(axes)

if __name__ == "__main__":
    for m, n in [(1, 1), (1, 2), (2, 2), (2, 3)]:
        total = matched = 0
        for g in product(svert(n), repeat=m + 1):
            g = list(g)
            total += 1
            if is_simplicial(induced(g)) == coord_injective(g):
                matched += 1
        assert matched == total
        print(f"S^{m} -> S^{n}: simpliciality == coordinate-injectivity on all {total} maps")
    print("Coordinate Injectivity Principle confirmed.")

"""Build the suspension tower explicitly and check exactness (excess preserved)."""
from __future__ import annotations
from typing import Dict, List, Tuple

Vertex = Tuple[int, bool]

def anti(p: Vertex) -> Vertex:
    i, b = p
    return (i, not b)

def induced(g: List[Vertex]) -> Dict[Vertex, Vertex]:
    f: Dict[Vertex, Vertex] = {}
    for i, v in enumerate(g):
        f[(i, True)] = v
        f[(i, False)] = anti(v)
    return f

def is_simplicial(f: Dict[Vertex, Vertex]) -> bool:
    return all(not (f[p] == anti(f[q]) and p != anti(q)) for p in f for q in f)

def susp_data(g: List[Vertex]) -> List[Vertex]:
    n = max(v[0] for v in g)
    return list(g) + [(n + 1, True)]

if __name__ == "__main__":
    g: List[Vertex] = [(0, True), (1, True)]  # fair map S^1 -> S^2
    m, n = 1, 2
    print(f"level 0: S^{m} -> S^{n}, excess = {n - m}, simplicial = {is_simplicial(induced(g))}")
    for k in range(1, 5):
        g = susp_data(g)
        m, n = m + 1, n + 1
        ok = is_simplicial(induced(g))
        assert ok and n - m == 1
        print(f"level {k}: S^{m} -> S^{n}, excess = {n - m}, simplicial = {ok}")
    print("Excess n - m preserved along the entire tower.")

